def text_of(r):
    if isinstance(r,str): r=json.loads(r)
    if isinstance(r,list): return r[0].get('content')
    c=r.get('content')
    if isinstance(c,dict):
        s=c.get('source',{})
        if s.get('type')=='base64':
            import base64,io
            from pypdf import PdfReader
            b=base64.b64decode(s['data']); rd=PdfReader(io.BytesIO(b))
            return "\n".join(p.extract_text() or '' for p in rd.pages)
        return s.get('data')
    return c
